def longestString(arr):
    arr.sort()
    max_len = 0
    result = ""
    n = len(arr)
    for i in range(n):
        current = arr[i]
        valid = True
        for j in range(1, len(current)):
            prefix = current[:j]
            if prefix not in arr:
                valid = False
                break
        if valid and len(current) > max_len:
            max_len = len(current)
            result = current
        elif valid and len(current) == max_len and current < result:
            result = current
    return result
